class Solution {
    unordered_map<int, vector<TreeNode*>> memo;
public:
    vector<TreeNode*> allPossibleFBT(int n) {
        if (n % 2 == 0) return {};
        if (n == 1) return {new TreeNode(0)};
        if (memo.count(n)) return memo[n];
        vector<TreeNode*> ans;
        for (int l = 1; l < n; l += 2) {
            int r = n - 1 - l;
            for (auto left_t : allPossibleFBT(l)) {
                for (auto right_t : allPossibleFBT(r)) {
                    TreeNode* root = new TreeNode(0, left_t, right_t);
                    ans.push_back(root);
                }
            }
        }
        return memo[n] = ans;
    }
};

class Solution {
    private Map<Integer, List<TreeNode>> memo = new HashMap<>();
    public List<TreeNode> allPossibleFBT(int n) {
        if (n % 2 == 0) return new ArrayList<>();
        if (n == 1) {
            List<TreeNode> base = new ArrayList<>();
            base.add(new TreeNode(0));
            return base;
        }
        if (memo.containsKey(n)) return memo.get(n);
        List<TreeNode> ans = new ArrayList<>();
        for (int l = 1; l < n; l += 2) {
            int r = n - 1 - l;
            for (TreeNode leftT : allPossibleFBT(l)) {
                for (TreeNode rightT : allPossibleFBT(r)) {
                    TreeNode root = new TreeNode(0, leftT, rightT);
                    ans.add(root);
                }
            }
        }
        memo.put(n, ans);
        return ans;
    }
}

